#define main preserved_native_main
#include "../nms-cuda/main.cu"
#undef main
#include <vector>
#include <string>
std::vector<unsigned char> readv(const char*name){FILE*f=fopen(name,"rb");if(!f){fprintf(stderr,"missing fixture %s\n",name);exit(3);}fseek(f,0,SEEK_END);size_t sz=ftell(f);rewind(f);std::vector<unsigned char>a(sz);if(fread(a.data(),1,sz,f)!=sz)exit(3);fclose(f);return a;}
int main(int argc,char**argv){bool mapmode=std::string(argv[1])=="map";auto input=readv("study_input_f32.bin"),expected=readv("study_expected_u8.bin");float4*points;unsigned char*bitmap,*keep;cudaMalloc(&points,input.size());cudaMemcpy(points,input.data(),input.size(),cudaMemcpyHostToDevice);cudaMalloc(&bitmap,4096*4096);cudaMalloc(&keep,4096);cudaMemset(bitmap,1,4096*4096);cudaMemset(keep,0,4096);
auto map=[&](){generate_nms_bitmap<<<dim3(256,256),dim3(16,16)>>>(points,bitmap,0.3f);};auto reduce=[&](){reduce_nms_bitmap<<<4096,128>>>(bitmap,keep,4096);};map();cudaDeviceSynchronize();reduce();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;bool allok=true;
for(int trial=1;trial<=5;trial++){cudaMemset(bitmap,1,4096*4096);cudaMemset(keep,0,4096);cudaDeviceSynchronize();if(!mapmode){map();cudaDeviceSynchronize();}auto start=std::chrono::steady_clock::now();for(int rep=0;rep<10;rep++){if(mapmode)map();else reduce();}auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;if(mapmode){reduce();status=cudaDeviceSynchronize();}std::vector<unsigned char>out(expected.size());cudaMemcpy(out.data(),bitmap,4096*4096,cudaMemcpyDeviceToHost);cudaMemcpy(out.data()+4096*4096,keep,4096,cudaMemcpyDeviceToHost);unsigned error=0;for(size_t i=0;i<out.size();i++)error=std::max(error,unsigned(abs(int(out[i])-int(expected[i]))));bool ok=status==cudaSuccess&&error==0;allok&=ok;std::vector<unsigned char>got=input;got.insert(got.end(),out.begin(),out.end());char name[80];snprintf(name,80,"output_trial%d.bin",trial);FILE*f=fopen(name,"wb");fwrite(got.data(),1,got.size(),f);fclose(f);
printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%u,\"max_rel_error\":%u,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size(),error,error,name,got.size());}return allok?0:1;}
